WITH page_profit AS ( SELECT wp.wp_url, SUM(ws.ws_net_profit) AS total_net_profit, SUM(p.p_cost) AS total_promo_cost, CASE WHEN hd.hd_vehicle_count > 2 THEN 'Multiple Vehicles' ELSE 'Few Vehicles' END AS vehicle_category FROM web_sales ws JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk GROUP BY wp.wp_url, hd.hd_vehicle_count ) SELECT wp_url, total_net_profit, total_promo_cost, vehicle_category, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM page_profit ORDER BY profit_rank LIMIT 10
